/* Guided lessons use authored prompts. Free text is saved, never claimed to be AI graded. */
window.createForXuanPaths=function(api){
 'use strict';
 const {D,esc,lines,pill,steps,source}=api;
 const labels=['先回想','分步示范','撤提示练习','解释与迁移'];
 const getPath=id=>D.paths.find(c=>c.id===id);
 const q=id=>D.questions.find(x=>x.id===id);
 const example=c=>D.cases.find(x=>x.id===c.example)||q(c.example);
 const attempt=(p,key)=>api.state().attempts.find(a=>a.id===p.responses?.[key]?.attemptId);
 const transferAttempt=(c,p)=>api.state().attempts.filter(a=>a.qid===c.transfer&&a.time>=p.startedAt).at(-1);
 const blank=()=>({stage:0,startedAt:Date.now(),updatedAt:Date.now(),revealed:0,prediction:'',reflection:'',checks:[],responses:{}});
 function current(c){const s=api.state();s.courses??={};if(!s.courses[c.id]){s.courses[c.id]=blank();api.save();}return s.courses[c.id];}
 function commit(p){p.updatedAt=Date.now();api.save();}
 function response(p,key){return p.responses[key]??={selected:[],confidence:'sure',assisted:false};}
 function button(text,action,attrs='',kind=''){return `<button class="button ${kind}" data-path-action="${action}" ${attrs}>${text}</button>`;}
 function topicName(id){return D.topics.find(t=>t.id===id)?.title||id;}
 function canReach(c,p,stage){if(stage===0)return true;if(!attempt(p,'warmup'))return false;if(stage===1)return true;if(p.revealed<example(c).steps.length)return false;if(stage===2)return true;return !!attempt(p,'exit')?.correct;}
 function card(c,i){const p=api.state().courses?.[c.id];return `<a class="card topic-card path-card" href="#path/${c.id}"><span class="index">${String(i+1).padStart(2,'0')}</span><span class="arrow">↗</span>${pill(topicName(c.id))}<h3>${esc(c.title)}</h3><p>${esc(c.goal)}</p><div class="mini-bar"><span style="width:${p?.completedAt?100:(p?.stage||0)*25}%"></span></div><span class="snapshot">${p?.completedAt?'已完成学习流程 · 继续跨日回测':p?'继续第 '+(p.stage+1)+' 步 · '+labels[p.stage]:'约25分钟起 · 长题可分次'}</span></a>`;}
 function list(){return `<div class="page-intro"><span class="eyebrow">GUIDED LEARNING / ONE STEP AT A TIME</span><h1 class="serif">一步一步，把方法学会</h1><p>先合上答案回想，再逐步观察示范，最后撤掉提示练一题。每一步保留过程；真题长问可以另分一次完成。</p></div><div class="path-how">${labels.map((s,i)=>`<div><b>0${i+1}</b><span>${s}</span></div>`).join('')}</div><div class="notice">跟练按条件、推导和使用边界展开。文字用于自我解释与复盘，证明过程可交由老师复核。完成课程流程与独立掌握分别记录。</div><div class="grid two">${D.paths.map(card).join('')}</div>`;}
 function homeWidget(){const started=D.paths.filter(c=>api.state().courses?.[c.id]&&!api.state().courses[c.id].completedAt).sort((a,b)=>api.state().courses[b.id].updatedAt-api.state().courses[a.id].updatedAt)[0];const c=started||D.paths[0];return `<div class="path-banner"><div><span class="eyebrow">NEW / 1对1跟练路线</span><h3>${started?'接着上次的一步':'先学方法，再把提示撤掉'}</h3><p>${esc(c.title)} · 回想 → 示范 → 练习 → 迁移</p></div><div class="actions"><a class="button" href="#path/${c.id}">${started?'继续跟练':'开始第一课'} →</a><a class="button secondary" href="#paths">全部8条路线</a></div></div>`;}
 function summary(){const started=D.paths.filter(c=>api.state().courses?.[c.id]);if(!started.length)return '';return `<div class="section-head"><h2 class="serif">跟练路线的进度</h2><a href="#paths">查看全部路线 ↗</a></div><div class="card"><p class="snapshot">这里记录学习流程；是否独立做对，仍以作答记录和跨日复测为准。</p>${started.map(c=>{const p=api.state().courses[c.id],a=transferAttempt(c,p);return `<div class="review-row"><span><a href="#path/${c.id}">${esc(c.title)}</a><small>${p.completedAt?'流程完成':'第 '+(p.stage+1)+' 步 · '+labels[p.stage]}${a?' · 迁移'+(a.self?'自评':'自动判分')+(a.correct?'通过':'需加强'):''}</small></span><a href="#path/${c.id}">继续 →</a></div>`;}).join('')}</div>`;}
 function options(question,r,graded){return `<div class="options" role="group" aria-label="${question.type==='multi'?'多选答案':'单选答案'}">${question.options.map((s,i)=>`<button class="option ${r.selected.includes(i)?'selected':''} ${graded?(question.correct.includes(i)?'correct':r.selected.includes(i)?'wrong':''):''}" data-path-action="select" data-index="${i}" aria-pressed="${r.selected.includes(i)}" ${graded?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(s)}</span></button>`).join('')}</div>`;}
 function checkpoint(c,p,key){const question=q(key==='warmup'?c.warmup:c.exit),r=response(p,key),a=attempt(p,key);const selectedWrong=a?.selected?.find(i=>!question.correct.includes(i));const missing=a?question.correct.filter(i=>!a.selected.includes(i)):[];
 return `<div class="row">${pill(key==='warmup'?'闭卷提取 · 先写再选':'同源变式 · 学习后巩固')}${pill(question.type==='multi'?'多选 · 全部选对才通过':'单项选择','amber')}</div><h2 style="margin:15px 0 0">${esc(question.title)}</h2><div class="question-stem">${lines(question.stem)}</div>${source(question)}${options(question,r,a)}${!a?`<fieldset class="confidence" style="border:0;padding:0"><legend>提交前，判断自己的把握</legend><label><input type="radio" name="path-confidence" value="sure" ${r.confidence==='sure'?'checked':''}>能说明理由</label><label><input type="radio" name="path-confidence" value="guess" ${r.confidence==='guess'?'checked':''}>有猜测 / 不确定</label></fieldset><div class="actions">${button('提交并核对','submit')}${button('我卡住了，给一点方向','coach','','secondary')}</div>${r.assisted?`<div class="notice"><b>从这一问重新开始：</b>${esc(c.coach[0])}<p style="margin:8px 0 0">${esc(c.coach[1])}</p><small>已记录为提示辅助；隔天可以再尝试独立回测。</small></div>`:''}`:`<div class="feedback ${a.correct?'':'error'}"><h3>${a.correct?'这条思路走通了':'先补这一处，再向前走'}</h3><p>正确答案：${question.correct.map(i=>'ABCD'[i]).join('')}。${a.independent?'本次为独立作答。':'本次为提示 / 猜测 / 同源巩固，不推进独立复习阶梯。'}</p>${!a.correct&&question.distractors?.[selectedWrong]?`<div class="callout"><b>根据所选答案，建议先检查</b><p>${esc(question.distractors[selectedWrong])}</p></div>`:''}${!a.correct&&missing.length?`<p>还需核对 ${missing.map(i=>'ABCD'[i]).join('、')} 项。逐项写依据，避免多选遗漏。</p>`:''}${steps(question)}<div class="cause-grid">${['范围与定义域','公式与模型','关键转换','计算与符号','论证与端点','猜对 / 不确定'].map(cause=>`<button data-path-action="cause" data-cause="${esc(cause)}" class="${a.cause===cause?'selected':''}">${cause}</button>`).join('')}</div></div><div class="actions" style="margin-top:18px">${key==='warmup'?button(a.correct?'进入分步示范 →':'带着更正，进入示范 →','advance'):a.correct?button('整理解释与迁移计划 →','advance'):button('先修复一环，再试一次','retry')}${key==='exit'?button('回到示范关键步骤','example-again','','secondary'):''}</div>`}`;
 }
 function worked(c,p){const e=example(c),all=p.revealed>=e.steps.length;return `<span class="label">分步示范 · ${esc(e.origin||'材料 '+e.photo)}</span><h2 style="margin-top:12px">${esc(e.title)}</h2><div class="question-stem">${lines(e.stem)}</div>${e.options?.length?`<ol class="example-options" type="A">${e.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol>`:''}${source(e)}<div class="callout"><b>先预判，不求一次说对</b><p>${esc(c.prediction)}</p></div><label for="path-prediction" class="label">写一句你的第一步</label><textarea id="path-prediction" class="written path-text" placeholder="我从……条件，想到先……，因为……">${esc(p.prediction)}</textarea><div class="notice">先写出猜想，再一次展开一步。文字只作为过程记录，不自动判对错。</div>${p.revealed?`<ol class="steps example-steps">${e.steps.slice(0,p.revealed).map(s=>`<li>${lines(s)}</li>`).join('')}</ol>`:''}${all?`<div class="recall"><b>完整答案</b><p>${esc(e.answer)}</p></div>${window.ForXuanDiagram?.(e)||''}<div class="actions">${button('合上示范，撤提示练一题 →','advance')}<a class="button secondary" href="#topic/${c.id}">补方法卡</a></div>`:`${button('展开第 '+(p.revealed+1)+' 步（共 '+e.steps.length+' 步）','reveal')}<p class="snapshot">展开解析会记录同源内容已看；不生成“做对”记录。</p>`}`;}
 function transfer(c,p){const target=q(c.transfer),a=transferAttempt(c,p),allChecks=c.checks.every((_,i)=>p.checks.includes(i));return `<span class="label">解释与迁移 / 把方法带走</span><h2 style="margin-top:12px">这次不是背住答案，而是说清依据</h2><div class="rubric">${c.checks.map((s,i)=>`<label><input type="checkbox" data-path-check="${i}" ${p.checks.includes(i)?'checked':''}>${esc(s)}（自检）</label>`).join('')}</div><label class="label" for="path-reflection">一句复盘：条件 → 方法 → 使用边界</label><textarea id="path-reflection" class="written path-text" placeholder="如：左移要替换整个 x；相位改变量还要乘角频率。">${esc(p.reflection)}</textarea><div class="callout"><b>${target.group==='gaokao'?'真题迁移':'换模型迁移 · 材料回测'}</b><p>${esc(target.title)}</p><small>${esc(target.origin)}</small><p>${a?'已有本轮作答：'+(a.self?'清单自评':'自动判分')+(a.correct?'通过':'需加强')+'；'+(a.independent?'独立完成。':'提示或同源巩固。'):'到训练页作答后，再从返回入口回到这里。长题可另分一次完成。'}</p>${button(a?'再做这道迁移题':'去做迁移题 →','transfer','','small')}</div>${p.completedAt?`<div class="notice"><b>本轮学习流程已完成。</b> ${a?.correct?'保留现在的理解，等待跨日复测。':'迁移仍有需要加强的环节，下一次从该题开始。'}<p>完成流程不等于独立掌握，提示与同日巩固不会升级复习阶梯。</p></div><div class="actions"><a class="button" href="#review">看复习安排 →</a><a class="button secondary" href="#paths">选下一条路线</a></div>`:`<div class="actions">${button('保存本轮复盘，完成学习流程','finish')}</div><p class="snapshot">完成条件：做过本轮迁移题、逐项自检并写一句复盘。现在${a?'已':'未'}作答迁移题，${allChecks?'已':'未'}完成全部自检。不会自动判定你的文字证明正确。</p>`}`;}
 function render(id){const c=getPath(id);if(!c)return '<div class="empty">没有找到这条路线。<a href="#paths">返回全部课程</a></div>';const p=current(c);while(p.stage>0&&!canReach(c,p,p.stage))p.stage--;return `<a class="breadcrumb" href="#paths">← 全部跟练路线</a><div class="page-intro"><span class="eyebrow">GUIDED LEARNING / ${esc(topicName(c.id))}</span><h1 class="serif">${esc(c.title)}</h1><p>${esc(c.goal)}</p></div><div class="path-stepper" aria-label="课程步骤">${labels.map((s,i)=>`<button data-path-action="step" data-index="${i}" class="${p.stage===i?'active':''}" aria-current="${p.stage===i?'step':'false'}" ${canReach(c,p,i)?'':'disabled'}><b>${i+1}</b><span>${s}</span></button>`).join('')}</div><div class="path-layout"><article class="card path-main">${p.stage===0?checkpoint(c,p,'warmup'):p.stage===1?worked(c,p):p.stage===2?checkpoint(c,p,'exit'):transfer(c,p)}</article><aside class="card path-side"><span class="label">带走一条方法</span><h3 style="margin-top:12px">${esc(topicName(c.id))}</h3><p>${esc(D.topics.find(t=>t.id===c.id).recall)}</p><div class="divider"></div><h3>卡住时，只退一环</h3><p>${esc(c.coach[2])}</p><a class="button ghost small" href="#topic/${c.id}">打开方法卡</a><p class="snapshot" style="margin-top:18px">自动保存当前步骤与文字。自评、自动判分、学习后巩固分别保留。</p></aside></div>`;}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-path-action]');if(!b)return;const c=getPath(location.hash.slice(1).split('/')[1]);if(!c)return;const p=current(c),key=p.stage===0?'warmup':'exit',r=response(p,key),act=b.dataset.pathAction,question=q(key==='warmup'?c.warmup:c.exit);
 if(act==='select'){if(attempt(p,key))return;const i=Number(b.dataset.index);r.selected=question.type==='multi'?(r.selected.includes(i)?r.selected.filter(x=>x!==i):[...r.selected,i]):[i];}
 else if(act==='submit'){if(attempt(p,key))return;if(!r.selected.length){api.toast('先写思路、选择答案，再提交。');return;}const a=api.record(question,r.selected,r.confidence,r.assisted,c.id);r.attemptId=a.id;}
 else if(act==='coach'){r.assisted=true;api.expose(question.related||question.id);}
 else if(act==='cause'){const a=attempt(p,key);if(a)a.cause=b.dataset.cause;}
 else if(act==='reveal'){if(p.prediction.trim().length<2){api.toast('先写一句第一步猜想，再展开示范。');document.getElementById('path-prediction')?.focus();return;}p.revealed=Math.min(example(c).steps.length,p.revealed+1);api.expose(example(c).related||example(c).id);}
 else if(act==='advance'){if(!canReach(c,p,p.stage+1)){api.toast('先完成当前步骤，再继续。');return;}p.stage=Math.min(3,p.stage+1);}
 else if(act==='step'){const stage=Number(b.dataset.index);if(canReach(c,p,stage))p.stage=stage;}
 else if(act==='retry'){p.responses.exit={selected:[],confidence:'sure',assisted:false};}
 else if(act==='example-again'){p.stage=1;}
 else if(act==='transfer'){commit(p);api.start(c.transfer,c.id);return;}
 else if(act==='finish'){if(!transferAttempt(c,p)){api.toast('请先作答迁移题，再回来复盘。');return;}if(!c.checks.every((_,i)=>p.checks.includes(i))||p.reflection.trim().length<4){api.toast('请逐项自检，并写一句自己的方法与边界。');return;}p.completedAt=Date.now();}
 commit(p);api.redraw();
 });
 document.addEventListener('input',e=>{if(!['path-prediction','path-reflection'].includes(e.target.id))return;const c=getPath(location.hash.slice(1).split('/')[1]);if(!c)return;const p=current(c);p[e.target.id==='path-prediction'?'prediction':'reflection']=e.target.value.slice(0,5000);commit(p);});
 document.addEventListener('change',e=>{const c=getPath(location.hash.slice(1).split('/')[1]);if(!c)return;const p=current(c);if(e.target.name==='path-confidence')response(p,p.stage===0?'warmup':'exit').confidence=e.target.value;if(e.target.matches('[data-path-check]')){const i=Number(e.target.dataset.pathCheck);p.checks=e.target.checked?[...new Set([...p.checks,i])]:p.checks.filter(x=>x!==i);}commit(p);});
 function merge(imported){if(!imported||typeof imported!=='object')return;const local=api.state().courses??={};for(const c of D.paths){const p=imported[c.id];if(!p||typeof p!=='object'||!Number.isFinite(p.startedAt)||!Number.isFinite(p.updatedAt)||p.startedAt<=0||p.updatedAt>Date.now()+86400000)continue;if(local[c.id]?.updatedAt>=p.updatedAt)continue;const clean={...blank(),startedAt:p.startedAt,updatedAt:p.updatedAt,stage:Math.max(0,Math.min(3,Number.isInteger(p.stage)?p.stage:0)),revealed:Math.max(0,Math.min(example(c).steps.length,Number.isInteger(p.revealed)?p.revealed:0)),prediction:String(p.prediction||'').slice(0,5000),reflection:String(p.reflection||'').slice(0,5000),checks:Array.isArray(p.checks)?[...new Set(p.checks.filter(i=>Number.isInteger(i)&&i>=0&&i<c.checks.length))]:[],responses:{}};for(const key of ['warmup','exit']){const r=p.responses?.[key];if(!r)continue;const expected=q(key==='warmup'?c.warmup:c.exit);clean.responses[key]={selected:Array.isArray(r.selected)?[...new Set(r.selected.filter(i=>Number.isInteger(i)&&i>=0&&i<expected.options.length))]:[],confidence:r.confidence==='guess'?'guess':'sure',assisted:!!r.assisted};if(api.state().attempts.some(a=>a.id===r.attemptId&&a.qid===expected.id))clean.responses[key].attemptId=r.attemptId;}if(Number.isFinite(p.completedAt)&&p.completedAt<=Date.now()+86400000&&canReach(c,clean,3)&&transferAttempt(c,clean)&&c.checks.every((_,i)=>clean.checks.includes(i))&&clean.reflection.trim().length>=4)clean.completedAt=p.completedAt;while(clean.stage>0&&!canReach(c,clean,clean.stage))clean.stage--;local[c.id]=clean;}}
 return {list,render,homeWidget,summary,merge};
};
